@module library  src=library.lua  loc=209  mode=chunk  self=lib
@deps cm, synthetic, libraryForm

# Imports
  @require util = 'util'  @ 4

# Private state
  @state lib = {}  @ 10

# Private functions
  -- Tier reads
  @fn synth(key)  @ 14
  @fn projectTier(key)  @ 15
  @fn libraryTier(key)  @ 16
  @fn factoryTier(key)  @ 17
  @fn asLibrary(key, value)  @ 21-24
      -- Some state is project-tier only; publish and modified compare the library
      -- *form* of each copy, not the copy itself. See docs/library.md § Modified badge.
  @fn sourceOf(key, name)  @ 28-30
      -- Publishable/revertable source for a name: the library copy, never the
      -- project copy. (The factory catalogue is a seed source, not a live source.)
  -- Tier writes
  @fn checkLevel(level)  @ 35-39
      -- The tiers a caller may name: factory is a seed source, not somewhere a name lives.
  @fn writeTier(level, key, name, value)  @ 42-46
      -- Read-modify-write a whole tier through one cm:set; cm deep-copies the value in.
  -- Names
  @fn sortedNames(tier, drop)  @ 50-57

# Public API (lib.*)
  @api lib.names(key)  @ 60-66
      @contract  { project, library } sorted names; synthetic floor dropped, no cross-dedup  @ 59
  -- Reads
  @api lib.getAt(key, level, name)  @ 71-74
      @contract  deep copy from the named tier alone; nil where that tier lacks the name  @ 70
  @api lib.modified(key, name)  @ 77-83
      @contract  true iff a project copy and a same-named source both exist and differ (util.deepEq)  @ 76
  -- Localize / fork
  @api lib.localize(key, name)  @ 88-95
      @contract  copy resolvable entry (library|factory floor) into project; no-op if synthetic/proj copy  @ 87
  @api lib.forkToProject(key, name)  @ 98-101
      @contract  localize then return the editable project copy  @ 97
  -- Author
  @api lib.save(key, level, name, value)  @ 106-110
      @contract  write a name into the named tier (cm:set deep-copies); synthetic names never  @ 105
  -- Publish / revert
  @api lib.publish(key, name)  @ 115-118
      @contract  project copy -> library tier (deepClone via cm:set); no-op when there is no project copy  @ 114
  @api lib.publishOverwrites(key, name)  @ 121-127
      @contract  true iff publish would overwrite a divergent library copy (both tiers exist and differ)  @ 120
  @api lib.revert(key, name)  @ 130-133
      @contract  library source -> project, discarding drift; no-op if no library copy exists  @ 129
  -- Factory seed / reload
  @api lib.seedIfEmpty(key)  @ 138-146
      @contract  stock an empty library tier from the factory catalogue; no-op once it holds anything  @ 137
  @api lib.reloadPlan(key)  @ 149-162
      @contract  { add = names in factory not library, overwrite = present but divergent }; both sorted  @ 148
  @api lib.factoryOverwrites(key, name)  @ 165-170
      @contract  true iff a factory import would overwrite a divergent library copy (both exist, differ)  @ 164
  @api lib.importFactory(key, name)  @ 173-177
      @contract  copy one factory entry into the library tier (deep-clone via cm:set); synthetic never  @ 172
  -- Tidy / delete
  @api lib.tidy(key, inUse)  @ 182-197
      @contract  drop project entries deepEq their source and not in inUse; single cm:set; returns removed  @ 181
  @api lib.delete(key, level, name)  @ 200-207
      @contract  remove name from tier level (project|global); synthetic names never  @ 199

